  await writeFile(path.join(directory, 'website/src/content/blog/future.mdx'), '---\ndraft: true\n---\nA draft.\n');
  await writeFile(path.join(directory, 'website/src/content/docs/docs/future.mdx'), '---\ndraft: true\n---\nA draft.\n');
